//! SC-007: a deliberate 100 Hz shift of a band edge toward the band is caught by both the
//! response check and the golden check (spec 004 tasks.md T024; research R-06). Three fixtures,
//! generated by `tools/filter-design/design_voiceband.py --shift-*`: the record high-pass up
//! 100 Hz, the record low-pass stopband edge down 100 Hz, the playback low-pass down 100 Hz.

#[path = "fixtures/shifted_playback_lp_down100.rs"]
mod playback_lp;
#[path = "fixtures/shifted_record_hp_up100.rs"]
mod record_hp;
#[path = "fixtures/shifted_record_lp_down100.rs"]
mod record_lp;

use rr_dr60::{Pipeline, Settings};
use rr_dr60_harness::checks::{self, Stage};
use rr_dr60_harness::golden;

fn record_hp_mutant(s: Settings) -> Pipeline {
    Pipeline::__with_stage_sos(
        s,
        record_hp::SHIFTED_RECORD_SOS,
        record_hp::SHIFTED_PLAYBACK_SOS,
    )
    .unwrap()
}

fn record_lp_mutant(s: Settings) -> Pipeline {
    Pipeline::__with_stage_sos(
        s,
        record_lp::SHIFTED_RECORD_SOS,
        record_lp::SHIFTED_PLAYBACK_SOS,
    )
    .unwrap()
}

fn playback_lp_mutant(s: Settings) -> Pipeline {
    Pipeline::__with_stage_sos(
        s,
        playback_lp::SHIFTED_RECORD_SOS,
        playback_lp::SHIFTED_PLAYBACK_SOS,
    )
    .unwrap()
}

fn failed_properties(results: &[rr_dr60_harness::checks::MeasurementResult]) -> Vec<&'static str> {
    results
        .iter()
        .filter(|r| !r.passed)
        .map(|r| r.property)
        .collect()
}

/// Spec 004 SC-007 (research R-06): each toward-band shift fails its stage's template on the
/// row the shift moves. The record high-pass up 100 Hz breaks the 225–2250 Hz loss maximum;
/// a low-pass stopband edge down 100 Hz breaks the loss at 2550 Hz (about 9–11 dB).
#[test]
fn record_hp_shift_is_caught() {
    let failed = failed_properties(&checks::check_stage_template(
        48_000,
        Stage::Record,
        &record_hp_mutant,
    ));
    assert!(
        failed.contains(&"loss 225-2250 Hz (max)"),
        "record high-pass shift not caught; failures: {failed:?}"
    );
}

#[test]
fn record_lp_shift_is_caught() {
    let failed = failed_properties(&checks::check_stage_template(
        48_000,
        Stage::Record,
        &record_lp_mutant,
    ));
    assert!(
        failed.contains(&"loss at 2550 Hz"),
        "record low-pass shift not caught; failures: {failed:?}"
    );
}

#[test]
fn playback_lp_shift_is_caught() {
    let failed = failed_properties(&checks::check_stage_template(
        48_000,
        Stage::Playback,
        &playback_lp_mutant,
    ));
    assert!(
        failed.contains(&"loss at 2550 Hz"),
        "playback low-pass shift not caught; failures: {failed:?}"
    );
}

/// Spec 004 SC-007: each mutant also fails the spec 001 golden check against the committed
/// file, which is the 6 kHz re-bless of T038 (the unmutated pipeline matches it, see
/// `tests/golden.rs`), so a failure here means the mutation changed the output, not the rate.
#[test]
fn golden_check_catches_shifted_band_edges() {
    let expected = golden::committed();
    for (name, mutant) in [
        ("record hp", record_hp_mutant as fn(Settings) -> Pipeline),
        ("record lp", record_lp_mutant),
        ("playback lp", playback_lp_mutant),
    ] {
        let actual = golden::generate(&mutant);
        let report = golden::compare(&expected, &actual).expect_err(name);
        assert!(
            report.contains("sweep_log/default/48000 Hz differs"),
            "{name}: {report}"
        );
    }
}

/// Spec 005 SC-007 (T035): a deliberate doubling of the default release, or a 3 dB shift of
/// the knee, is caught by both a tolerance check and the AGC golden check. The mutants are
/// built through the harness's `Make` factory with altered public settings (005 research R-08);
/// the plan's `__with_limiter_mutation` hook was not needed and was not kept
/// (contracts/rust-api.md › Test hooks).
mod agc {
    use rr_dr60::{Pipeline, Settings};
    use rr_dr60_harness::agc_checks;
    use rr_dr60_harness::golden;

    fn release_x2(mut s: Settings) -> Pipeline {
        s.agc.release_ms *= 2.0; // engineering target (005 SC-007)
        Pipeline::new(s).unwrap()
    }

    /// −3 dB (the default is −1 dBFS; +3 would also be in range since the knee moved, but −3
    /// stays the mutant the golden file was blessed against).
    fn knee_minus_3(mut s: Settings) -> Pipeline {
        s.agc.knee_dbfs -= 3.0; // engineering target (005 SC-007)
        Pipeline::new(s).unwrap()
    }

    fn failed_properties(
        results: &[rr_dr60_harness::checks::MeasurementResult],
    ) -> Vec<&'static str> {
        results
            .iter()
            .filter(|r| !r.passed)
            .map(|r| r.property)
            .collect()
    }

    #[test]
    fn release_change_is_caught() {
        // The FR-006 −1 dB release-time row: 2.72 s against 0.82–1.92 s.
        let failed = failed_properties(&agc_checks::check_fr006_release(48_000, &release_x2));
        assert!(
            failed.contains(&"release time to -1 dB"),
            "not caught; failures: {failed:?}"
        );
        let diff = golden::compare(&golden::committed_agc(), &golden::generate_agc(&release_x2));
        assert!(diff.is_err(), "AGC golden check missed the release change");
    }

    #[test]
    fn knee_change_is_caught() {
        // The ceiling rows cannot catch a knee shift (the ceiling is derived from the bisected
        // knee); the knee row does (005 T035).
        let failed = failed_properties(&agc_checks::check_fr004_static(48_000, &knee_minus_3));
        assert!(
            failed.contains(&"knee (-1 dB gain point) by bisection"),
            "not caught; failures: {failed:?}"
        );
        let diff = golden::compare(
            &golden::committed_agc(),
            &golden::generate_agc(&knee_minus_3),
        );
        assert!(diff.is_err(), "AGC golden check missed the knee change");
    }
}

/// Spec 003 SC-007, kept by spec 005 SC-007 (T035): a deliberate change of the default hang
/// time by 20 %, or of the threshold by 3 dB (−40 → −37 dBFS since spec 005, A-022 revised),
/// is caught by both a tolerance check and the VAS golden check. The mutants are built through
/// the harness's `Make` factory with altered public settings, with no hidden hooks.
mod vas {
    use rr_dr60::{Pipeline, Settings};
    use rr_dr60_harness::golden;
    use rr_dr60_harness::vas_checks;

    fn hang_x1_2(mut s: Settings) -> Pipeline {
        s.vas.hang_ms *= 1.2; // 20 %, engineering target (003 FR-017; SC-007)
        Pipeline::new(s).unwrap()
    }

    fn threshold_plus_3(mut s: Settings) -> Pipeline {
        s.vas.threshold_dbfs += 3.0; // 3 dB, engineering target (003 FR-017; SC-007)
        Pipeline::new(s).unwrap()
    }

    fn failed_properties(
        results: &[rr_dr60_harness::checks::MeasurementResult],
    ) -> Vec<&'static str> {
        results
            .iter()
            .filter(|r| !r.passed)
            .map(|r| r.property)
            .collect()
    }

    #[test]
    fn hang_change_is_caught() {
        let defaults = vas_checks::matrix()[0];
        let failed =
            failed_properties(&vas_checks::check_fr008_hang(48_000, &defaults, &hang_x1_2));
        assert!(
            failed.contains(&"kept part of the gap"),
            "not caught; failures: {failed:?}"
        );
        let diff = golden::compare(&golden::committed_vas(), &golden::generate_vas(&hang_x1_2));
        assert!(diff.is_err(), "VAS golden check missed the hang change");
    }

    #[test]
    fn threshold_change_is_caught() {
        let defaults = vas_checks::matrix()[0];
        let failed = failed_properties(&vas_checks::check_fr006_threshold(
            48_000,
            &defaults,
            &threshold_plus_3,
        ));
        assert!(
            failed.contains(&"threshold at 1 kHz − nominal"),
            "not caught; failures: {failed:?}"
        );
        let diff = golden::compare(
            &golden::committed_vas(),
            &golden::generate_vas(&threshold_plus_3),
        );
        assert!(
            diff.is_err(),
            "VAS golden check missed the threshold change"
        );
    }
}

/// Spec 006 SC-002, SC-004 (T039): the two harness-side split mutants (research R-08) against
/// the golden equivalence: a recording missing its first stored sample no longer reproduces
/// the golden entry's SHA-256, and a flipped CRC bit is refused at import. The mutants are
/// transforms of exported bytes (`split_checks::mutants`), never in the core; `us3_export_import`
/// proves the same two mutants fail the round-trip check.
mod split {
    use rr_dr60::Pipeline;
    use rr_dr60_harness::split_checks::{self, mutants};
    use rr_dr60_harness::{configs, golden};

    /// The `tone_1k_m20` / `default` golden entry at 48 kHz, recorded, exported, mutated,
    /// imported into a fresh engine and played: its SHA-256 differs from the entry's.
    #[test]
    fn drop_first_sample_breaks_the_golden_equivalence() {
        let a = golden::applicable_entries()
            .into_iter()
            .find(|a| {
                a.stimulus == "tone_1k_m20" && a.config == "default" && a.host_rate_hz == 48_000
            })
            .expect("entry");
        let x = golden::stimulus(a.stimulus, 48_000);
        let mut p = Pipeline::new(a.settings).unwrap();
        p.start_recording().unwrap();
        let _ = p.record(&x, &mut []).unwrap();
        let _ = p.stop_recording(&mut []).unwrap();
        let bytes = split_checks::export_bytes(&p, 1);
        let n = a.entry.n_samples as usize;
        // Healthy: reproduced.
        let mut healthy = Pipeline::new(a.settings).unwrap();
        assert_eq!(healthy.import(&bytes), Ok(1));
        let out = split_checks::play_to_end(&mut healthy, 1, 997);
        let pre = &out[..out.len() - healthy.drain_samples() as usize];
        assert_eq!(
            golden::entry(a.stimulus, a.config, 48_000, &pre[..n]).sha256,
            a.entry.sha256
        );
        // Mutant: caught.
        let mut mutant = Pipeline::new(a.settings).unwrap();
        assert_eq!(mutant.import(&mutants::drop_first_sample(&bytes)), Ok(1));
        let out = split_checks::play_to_end(&mut mutant, 1, 997);
        let pre = &out[..out.len() - mutant.drain_samples() as usize];
        assert!(
            pre.len() < n
                || golden::entry(a.stimulus, a.config, 48_000, &pre[..n]).sha256 != a.entry.sha256
        );
    }

    /// A flipped CRC bit never reaches the memory.
    #[test]
    fn crc_bit_flip_is_refused() {
        let mut p = Pipeline::new(configs::settings("default_agc", 48_000)).unwrap();
        p.start_recording().unwrap();
        let _ = p
            .record(&golden::stimulus("tone_1k_m20", 48_000), &mut [])
            .unwrap();
        let _ = p.stop_recording(&mut []).unwrap();
        let bytes = split_checks::export_bytes(&p, 1);
        let before = p.memory_status();
        assert_eq!(
            p.import(&mutants::flip_crc_bit(&bytes)),
            Err(rr_dr60::Error::Damaged)
        );
        assert_eq!(p.memory_status(), before);
        assert_eq!(p.import(&bytes), Ok(2));
    }
}
